import data from '../data/contributors.json';

interface Contributor {
  login: string;
  /** False for CodePlex-era authors with no GitHub account behind the commits. */
  linked: boolean;
  html_url: string | null;
  avatar_url: string | null;
  gen2: number;
  gen3: number;
  contributions: number;
}

// Generated by scripts/fetch-contributors.mjs and refreshed on every deploy,
// so the wall is GitHub data without a single request from the visitor's
// browser. Fetching it client-side is what broke before: api.github.com
// allows 60 requests/hour per IP unauthenticated, so the wall emptied out to
// its hardcoded fallback for everyone after the first few visitors.
const CONTRIBUTORS = data.contributors as Contributor[];

const fmt = new Intl.NumberFormat('en-US');

/** "Gen2 · 2,907 commits" — what the avatar's tooltip and its label say. */
function describe(c: Contributor): string {
  const gens = [c.gen2 > 0 && 'Gen2', c.gen3 > 0 && 'Gen3'].filter(Boolean).join(' + ');
  return `${gens} · ${fmt.format(c.contributions)} commit${c.contributions === 1 ? '' : 's'}`;
}

export function Contributors() {
  return (
    <section className="section" id="contributors">
      <div className="container">
        <div className="section-head" data-reveal>
          <div className="cs-eyebrow">// the people</div>
          <h2 className="cs-h1">Built by the community.</h2>
          <p className="section-sub">
            Every author in the Cosmos history — {fmt.format(CONTRIBUTORS.length)} people
            across both generations, from the 2007 proof of concept to Gen3.
          </p>
        </div>
        <div className="avatar-wall" data-reveal>
          {CONTRIBUTORS.map(c => {
            const isGen3 = c.gen3 > 0;
            const label = `${c.login} — ${describe(c)}`;
            const inner = (
              <>
                {c.avatar_url
                  ? <img src={c.avatar_url} alt="" loading="lazy" decoding="async" />
                  : <span className="avatar-fallback">{c.login.slice(0, 2).toUpperCase()}</span>}
                {isGen3 && <span className="avatar-badge" aria-hidden="true">G3</span>}
              </>
            );
            // No GitHub account to open, so it must not be a link — a link
            // that goes nowhere is worse than a plain avatar. role="img"
            // carries the name that the anchor's aria-label carries below.
            return c.linked && c.html_url ? (
              <a
                key={c.login}
                className={'avatar' + (isGen3 ? ' avatar-gen3' : '')}
                href={c.html_url}
                target="_blank"
                rel="noreferrer"
                aria-label={`${label} — GitHub profile`}
                title={label}
              >
                {inner}
              </a>
            ) : (
              <span
                key={c.login}
                className={'avatar' + (isGen3 ? ' avatar-gen3' : '')}
                role="img"
                aria-label={label}
                title={label}
              >
                {inner}
              </span>
            );
          })}
        </div>
      </div>
    </section>
  );
}
